1	package com.example.starter.plan.service;
2	
3	import com.example.starter.plan.model.DayPlan;
4	import com.example.starter.plan.model.Occupancy;
5	import com.example.starter.plan.model.PlanStatus;
6	import com.example.starter.plan.model.PublishedSlot;
7	import com.example.starter.plan.repo.IdempotencyRepository;
8	import com.example.starter.plan.repo.PlanRepository;
9	import com.example.starter.plan.web.ApiException;
10	import com.example.starter.plan.web.dto.CreatePlanRequest;
11	import com.example.starter.plan.web.dto.OccupancyRequest;
12	import com.example.starter.plan.web.dto.OccupancyView;
13	import com.example.starter.plan.web.dto.PlanResponse;
14	import com.example.starter.plan.web.dto.PublishedSlotView;
15	import com.example.starter.plan.web.dto.UpdateOccupanciesRequest;
16	import com.fasterxml.jackson.databind.ObjectMapper;
17	import java.nio.charset.StandardCharsets;
18	import java.security.MessageDigest;
19	import java.security.NoSuchAlgorithmException;
20	import java.time.Instant;
21	import java.time.LocalDate;
22	import java.time.ZoneId;
23	import java.util.ArrayList;
24	import java.util.Comparator;
25	import java.util.LinkedHashMap;
26	import java.util.List;
27	import java.util.Map;
28	import java.util.Optional;
29	import java.util.TreeSet;
30	import org.springframework.dao.DuplicateKeyException;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.stereotype.Service;
33	import org.springframework.transaction.PlatformTransactionManager;
34	import org.springframework.transaction.support.TransactionTemplate;
35	
36	/**
37	 * 铁路走廊日计划核心业务：草稿创建/整体替换、发布、取消与查询。
38	 *
39	 * <p>并发与幂等约定：写操作按 (操作类型, requestKey) 幂等，同键同参重放返回首次成功结果，
40	 * 同键不同参返回 409；发布经全局发布锁串行化，同一计划的更新/发布/取消经行锁按事务提交顺序生效；
41	 * 仅成功结果写入幂等记录，失败（含 422 时隙冲突）不缓存、可修正后重试。
42	 */
43	@Service
44	public class PlanService {
45	
46	    /** 运营日解释时区。 */
47	    public static final ZoneId OPERATION_ZONE = ZoneId.of("Asia/Shanghai");
48	
49	    private static final String OP_CREATE = "CREATE";
50	    private static final String OP_UPDATE = "UPDATE";
51	    private static final String OP_PUBLISH = "PUBLISH";
52	    private static final String OP_CANCEL = "CANCEL";
53	
54	    private final PlanRepository planRepo;
55	    private final IdempotencyRepository idemRepo;
56	    private final ObjectMapper objectMapper;
57	    private final TransactionTemplate tx;
58	
59	    public PlanService(PlanRepository planRepo, IdempotencyRepository idemRepo,
60	                       ObjectMapper objectMapper, PlatformTransactionManager txManager) {
61	        this.planRepo = planRepo;
62	        this.idemRepo = idemRepo;
63	        this.objectMapper = objectMapper;
64	        this.tx = new TransactionTemplate(txManager);
65	    }
66	
67	    /**
68	     * 创建草稿计划（版本 1，状态 DRAFT）。
69	     */
70	    public PlanResponse createDraft(CreatePlanRequest req) {
71	        validateOccupancyParams(req.occupancies());
72	        validateWithinOperationDay(req.occupancies(), req.opDate());
73	        String hash = hashCreate(req);
74	        Optional<PlanResponse> replay = replayIfPresent(OP_CREATE, req.requestKey(), hash);
75	        if (replay.isPresent()) {
76	            return replay.get();
77	        }
78	        try {
79	            return tx.execute(status -> {
80	                if (planRepo.findByKey(req.scheduleKey()).isPresent()) {
81	                    throw conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在: " + req.scheduleKey());
82	                }
83	                long now = System.currentTimeMillis();
84	                long planId = planRepo.insertPlan(req.scheduleKey(), req.opDate(), PlanStatus.DRAFT, now);
85	                planRepo.insertOccupancies(planId, toOccupancies(planId, req.occupancies()));
86	                PlanResponse response = loadPlan(req.scheduleKey());
87	                idemRepo.insert(OP_CREATE, req.requestKey(), hash, toJson(response), now);
88	                return response;
89	            });
90	        } catch (DuplicateKeyException e) {
91	            return resolveDuplicate(OP_CREATE, req.requestKey(), hash);
92	        }
93	    }
94	
95	    /**
96	     * 整体替换草稿占用清单，版本加一；仅 DRAFT 可改，expectedVersion 必须匹配。
97	     */
98	    public PlanResponse replaceOccupancies(String scheduleKey, UpdateOccupanciesRequest req) {
99	        validateOccupancyParams(req.occupancies());
100	        String hash = hashUpdate(scheduleKey, req);
101	        Optional<PlanResponse> replay = replayIfPresent(OP_UPDATE, req.requestKey(), hash);
102	        if (replay.isPresent()) {
103	            return replay.get();
104	        }
105	        try {
106	            return tx.execute(status -> {
107	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
108	                        .orElseThrow(() -> notFound(scheduleKey));
109	                if (plan.status() != PlanStatus.DRAFT) {
110	                    throw conflict("PLAN_STATE_CONFLICT",
111	                            "仅草稿可修改占用，当前状态: " + plan.status());
112	                }
113	                if (req.expectedVersion() != plan.version()) {
114	                    throw conflict("VERSION_CONFLICT",
115	                            "expectedVersion=" + req.expectedVersion() + " 与当前版本 " + plan.version() + " 不一致");
116	                }
117	                validateWithinOperationDay(req.occupancies(), plan.opDate());
118	                long now = System.currentTimeMillis();
119	                planRepo.replaceOccupancies(plan.id(), toOccupancies(plan.id(), req.occupancies()));
120	                planRepo.updateVersionAndStatus(plan.id(), plan.version() + 1, PlanStatus.DRAFT, now);
121	                PlanResponse response = loadPlan(scheduleKey);
122	                idemRepo.insert(OP_UPDATE, req.requestKey(), hash, toJson(response), now);
123	                return response;
124	            });
125	        } catch (DuplicateKeyException e) {
126	            return resolveDuplicate(OP_UPDATE, req.requestKey(), hash);
127	        }
128	    }
129	
130	    /**
131	     * 发布计划：全局发布锁内原子校验本计划列车重叠与跨计划区段重叠，
132	     * 任一冲突则整张计划保持草稿并抛出 422（携带冲突区段与计划）。
133	     */
134	    public PlanResponse publish(String scheduleKey, String requestKey) {
135	        String hash = hashAction(OP_PUBLISH, scheduleKey);
136	        Optional<PlanResponse> replay = replayIfPresent(OP_PUBLISH, requestKey, hash);
137	        if (replay.isPresent()) {
138	            return replay.get();
139	        }
140	        try {
141	            return tx.execute(status -> {
142	                planRepo.acquirePublishLock();
143	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
144	                        .orElseThrow(() -> notFound(scheduleKey));
145	                if (plan.status() != PlanStatus.DRAFT) {
146	                    throw conflict("PLAN_STATE_CONFLICT",
147	                            "仅草稿可发布，当前状态: " + plan.status());
148	                }
149	                List<Occupancy> occupancies = planRepo.findOccupancies(plan.id());
150	                List<Map<String, Object>> conflicts = new ArrayList<>();
151	                conflicts.addAll(findTrainOverlaps(scheduleKey, occupancies));
152	                conflicts.addAll(findSectionConflicts(plan, occupancies));
153	                if (!conflicts.isEmpty()) {
154	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT",
155	                            "存在时隙冲突，计划保持草稿", conflicts);
156	                }
157	                long now = System.currentTimeMillis();
158	                planRepo.updateStatus(plan.id(), PlanStatus.PUBLISHED, now);
159	                PlanResponse response = loadPlan(scheduleKey);
160	                idemRepo.insert(OP_PUBLISH, requestKey, hash, toJson(response), now);
161	                return response;
162	            });
163	        } catch (DuplicateKeyException e) {
164	            return resolveDuplicate(OP_PUBLISH, requestKey, hash);
165	        }
166	    }
167	
168	    /**
169	     * 取消已发布计划：时隙立即释放，历史计划与占用保留不改写。
170	     */
171	    public PlanResponse cancel(String scheduleKey, String requestKey) {
172	        String hash = hashAction(OP_CANCEL, scheduleKey);
173	        Optional<PlanResponse> replay = replayIfPresent(OP_CANCEL, requestKey, hash);
174	        if (replay.isPresent()) {
175	            return replay.get();
176	        }
177	        try {
178	            return tx.execute(status -> {
179	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
180	                        .orElseThrow(() -> notFound(scheduleKey));
181	                if (plan.status() != PlanStatus.PUBLISHED) {
182	                    throw conflict("PLAN_STATE_CONFLICT",
183	                            "仅已发布计划可取消，当前状态: " + plan.status());
184	                }
185	                long now = System.currentTimeMillis();
186	                planRepo.updateStatus(plan.id(), PlanStatus.CANCELLED, now);
187	                PlanResponse response = loadPlan(scheduleKey);
188	                idemRepo.insert(OP_CANCEL, requestKey, hash, toJson(response), now);
189	                return response;
190	            });
191	        } catch (DuplicateKeyException e) {
192	            return resolveDuplicate(OP_CANCEL, requestKey, hash);
193	        }
194	    }
195	
196	    /**
197	     * 按计划业务键查询明细（含历史占用），不存在返回 404。
198	     */
199	    public PlanResponse getPlan(String scheduleKey) {
200	        if (planRepo.findByKey(scheduleKey).isEmpty()) {
201	            throw notFound(scheduleKey);
202	        }
203	        return loadPlan(scheduleKey);
204	    }
205	
206	    /**
207	     * 查询指定运营日与区段上当前已发布的生效时隙。
208	     */
209	    public List<PublishedSlotView> getPublishedSlots(LocalDate opDate, String sectionId) {
210	        return planRepo.findPublishedSlots(opDate, List.of(sectionId), -1L).stream()
211	                .map(s -> new PublishedSlotView(s.scheduleKey(), s.trainNo(), s.sectionId(),
212	                        s.startUtc(), s.endUtc()))
213	                .toList();
214	    }
215	
216	    // ---------- 内部实现 ----------
217	
218	    private PlanResponse loadPlan(String scheduleKey) {
219	        DayPlan plan = planRepo.findByKey(scheduleKey)
220	                .orElseThrow(() -> notFound(scheduleKey));
221	        List<OccupancyView> views = planRepo.findOccupancies(plan.id()).stream()
222	                .map(o -> new OccupancyView(o.trainNo(), o.sectionId(), o.startUtc(), o.endUtc()))
223	                .toList();
224	        return new PlanResponse(plan.scheduleKey(), plan.opDate(), plan.version(),
225	                plan.status().name(), views);
226	    }
227	
228	    private List<Occupancy> toOccupancies(long planId, List<OccupancyRequest> requests) {
229	        List<Occupancy> result = new ArrayList<>(requests.size());
230	        for (int i = 0; i < requests.size(); i++) {
231	            OccupancyRequest r = requests.get(i);
232	            result.add(new Occupancy(0L, planId, i, r.trainNo(), r.sectionId(), r.startUtc(), r.endUtc()));
233	        }
234	        return result;
235	    }
236	
237	    /**
238	     * 参数级校验：结束必须晚于开始，且起止落在同一 Asia/Shanghai 日历日内。
239	     */
240	    private void validateOccupancyParams(List<OccupancyRequest> occupancies) {
241	        for (int i = 0; i < occupancies.size(); i++) {
242	            OccupancyRequest o = occupancies.get(i);
243	            if (!o.endUtc().isAfter(o.startUtc())) {
244	                throw badRequest("第 " + i + " 条占用结束时刻必须晚于开始时刻");
245	            }
246	            LocalDate startDay = o.startUtc().atZone(OPERATION_ZONE).toLocalDate();
247	            LocalDate endDay = o.endUtc().minusNanos(1).atZone(OPERATION_ZONE).toLocalDate();
248	            if (!startDay.equals(endDay)) {
249	                throw badRequest("第 " + i + " 条占用必须落在同一运营日（Asia/Shanghai）内");
250	            }
251	        }
252	    }
253	
254	    /**
255	     * 占用必须落在计划运营日内：[start, end) 完全包含于运营日 [dayStart, dayEnd)。
256	     */
257	    private void validateWithinOperationDay(List<OccupancyRequest> occupancies, LocalDate opDate) {
258	        Instant dayStart = opDate.atStartOfDay(OPERATION_ZONE).toInstant();
259	        Instant dayEnd = opDate.plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
260	        for (int i = 0; i < occupancies.size(); i++) {
261	            OccupancyRequest o = occupancies.get(i);
262	            if (o.startUtc().isBefore(dayStart) || o.endUtc().isAfter(dayEnd)) {
263	                throw badRequest("第 " + i + " 条占用不在运营日 " + opDate + "（Asia/Shanghai）内");
264	            }
265	        }
266	    }
267	
268	    /**
269	     * 本计划内同一列车的重叠占用检测（左闭右开，相邻合法）。
270	     */
271	    private List<Map<String, Object>> findTrainOverlaps(String scheduleKey, List<Occupancy> occupancies) {
272	        List<Map<String, Object>> conflicts = new ArrayList<>();
273	        Map<String, List<Occupancy>> byTrain = new LinkedHashMap<>();
274	        for (Occupancy o : occupancies) {
275	            byTrain.computeIfAbsent(o.trainNo(), k -> new ArrayList<>()).add(o);
276	        }
277	        byTrain.forEach((trainNo, list) -> {
278	            List<Occupancy> sorted = list.stream()
279	                    .sorted(Comparator.comparing(Occupancy::startUtc)).toList();
280	            for (int i = 1; i < sorted.size(); i++) {
281	                Occupancy prev = sorted.get(i - 1);
282	                Occupancy cur = sorted.get(i);
283	                if (cur.startUtc().isBefore(prev.endUtc())) {
284	                    Map<String, Object> detail = new LinkedHashMap<>();
285	                    detail.put("type", "TRAIN_OVERLAP");
286	                    detail.put("scheduleKey", scheduleKey);
287	                    detail.put("trainNo", trainNo);
288	                    detail.put("sectionId", cur.sectionId());
289	                    detail.put("startUtc", cur.startUtc().toString());
290	                    detail.put("endUtc", cur.endUtc().toString());
291	                    conflicts.add(detail);
292	                }
293	            }
294	        });
295	        return conflicts;
296	    }
297	
298	    /**
299	     * 与其他已发布计划在同日期、同区段上的重叠检测（左闭右开，相邻合法）。
300	     */
301	    private List<Map<String, Object>> findSectionConflicts(DayPlan plan, List<Occupancy> occupancies) {
302	        List<String> sectionIds = occupancies.stream()
303	                .map(Occupancy::sectionId)
304	                .collect(java.util.stream.Collectors.toCollection(TreeSet::new))
305	                .stream().toList();
306	        List<PublishedSlot> published = planRepo.findPublishedSlots(plan.opDate(), sectionIds, plan.id());
307	        List<Map<String, Object>> conflicts = new ArrayList<>();
308	        for (Occupancy o : occupancies) {
309	            for (PublishedSlot slot : published) {
310	                if (!o.sectionId().equals(slot.sectionId())) {
311	                    continue;
312	                }
313	                boolean overlap = o.startUtc().isBefore(slot.endUtc())
314	                        && slot.startUtc().isBefore(o.endUtc());
315	                if (overlap) {
316	                    Map<String, Object> detail = new LinkedHashMap<>();
317	                    detail.put("type", "SECTION_CONFLICT");
318	                    detail.put("sectionId", o.sectionId());
319	                    detail.put("scheduleKey", plan.scheduleKey());
320	                    detail.put("conflictingScheduleKey", slot.scheduleKey());
321	                    detail.put("trainNo", o.trainNo());
322	                    detail.put("startUtc", o.startUtc().toString());
323	                    detail.put("endUtc", o.endUtc().toString());
324	                    conflicts.add(detail);
325	                }
326	            }
327	        }
328	        return conflicts;
329	    }
330	
331	    /**
332	     * 幂等重放：存在记录且参数一致返回首次结果；参数不一致抛 409。
333	     */
334	    private Optional<PlanResponse> replayIfPresent(String opType, String requestKey, String hash) {
335	        return idemRepo.find(opType, requestKey).map(record -> {
336	            if (!record.requestHash().equals(hash)) {
337	                throw conflict("IDEMPOTENT_KEY_REUSED",
338	                        "requestKey 已用于其他参数: " + requestKey);
339	            }
340	            return fromJson(record.responseJson());
341	        });
342	    }
343	
344	    /**
345	     * 并发下唯一键冲突后的裁决：若为同键重放返回首次结果，否则说明 scheduleKey 冲突。
346	     */
347	    private PlanResponse resolveDuplicate(String opType, String requestKey, String hash) {
348	        return replayIfPresent(opType, requestKey, hash)
349	                .orElseThrow(() -> conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在"));
350	    }
351	
352	    private String hashCreate(CreatePlanRequest req) {
353	        StringBuilder sb = new StringBuilder(OP_CREATE).append('\n')
354	                .append(req.scheduleKey()).append('\n').append(req.opDate());
355	        appendOccupancies(sb, req.occupancies());
356	        return sha256(sb.toString());
357	    }
358	
359	    private String hashUpdate(String scheduleKey, UpdateOccupanciesRequest req) {
360	        StringBuilder sb = new StringBuilder(OP_UPDATE).append('\n')
361	                .append(scheduleKey).append('\n').append(req.expectedVersion());
362	        appendOccupancies(sb, req.occupancies());
363	        return sha256(sb.toString());
364	    }
365	
366	    private String hashAction(String opType, String scheduleKey) {
367	        return sha256(opType + '\n' + scheduleKey);
368	    }
369	
370	    private void appendOccupancies(StringBuilder sb, List<OccupancyRequest> occupancies) {
371	        for (OccupancyRequest o : occupancies) {
372	            sb.append('\n').append(o.trainNo()).append('|').append(o.sectionId()).append('|')
373	                    .append(o.startUtc().toEpochMilli()).append('|').append(o.endUtc().toEpochMilli());
374	        }
375	    }
376	
377	    private String sha256(String text) {
378	        try {
379	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
380	            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
381	            StringBuilder hex = new StringBuilder(hashed.length * 2);
382	            for (byte b : hashed) {
383	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
384	                hex.append(Character.forDigit(b & 0xF, 16));
385	            }
386	            return hex.toString();
387	        } catch (NoSuchAlgorithmException e) {
388	            throw new IllegalStateException(e);
389	        }
390	    }
391	
392	    private String toJson(PlanResponse response) {
393	        try {
394	            return objectMapper.writeValueAsString(response);
395	        } catch (Exception e) {
396	            throw new IllegalStateException("响应序列化失败", e);
397	        }
398	    }
399	
400	    private PlanResponse fromJson(String json) {
401	        try {
402	            return objectMapper.readValue(json, PlanResponse.class);
403	        } catch (Exception e) {
404	            throw new IllegalStateException("幂等响应反序列化失败", e);
405	        }
406	    }
407	
408	    private ApiException badRequest(String message) {
409	        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
410	    }
411	
412	    private ApiException notFound(String scheduleKey) {
413	        return new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
414	                "计划不存在: " + scheduleKey);
415	    }
416	
417	    private ApiException conflict(String code, String message) {
418	        return new ApiException(HttpStatus.CONFLICT, code, message);
419	    }
420	}
