2	
3	import com.example.starter.plan.model.DayPlan;
4	import com.example.starter.plan.model.Occupancy;
5	import com.example.starter.plan.model.PlanStatus;
6	import com.example.starter.plan.model.PublishedSlot;
7	import java.sql.Date;
8	import java.sql.PreparedStatement;
9	import java.sql.Statement;
10	import java.time.Instant;
11	import java.time.LocalDate;
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Optional;
15	import java.util.StringJoiner;
16	import org.springframework.jdbc.core.JdbcTemplate;
17	import org.springframework.jdbc.core.RowMapper;
18	import org.springframework.jdbc.support.GeneratedKeyHolder;
19	import org.springframework.jdbc.support.KeyHolder;
20	import org.springframework.stereotype.Repository;
21	
22	/**
23	 * 日计划与占用的 JDBC 持久化。所有时刻以 UTC 毫秒存储，时区无关。
24	 */
25	@Repository
26	public class PlanRepository {
27	
28	    private static final RowMapper<DayPlan> PLAN_MAPPER = (rs, n) -> new DayPlan(
29	            rs.getLong("id"),
30	            rs.getString("schedule_key"),
31	            rs.getObject("op_date", LocalDate.class),
32	            rs.getInt("version"),
33	            PlanStatus.valueOf(rs.getString("status")));
34	
35	    private static final RowMapper<Occupancy> OCCUPANCY_MAPPER = (rs, n) -> new Occupancy(
36	            rs.getLong("id"),
37	            rs.getLong("plan_id"),
38	            rs.getInt("seq"),
39	            rs.getString("train_no"),
40	            rs.getString("section_id"),
41	            Instant.ofEpochMilli(rs.getLong("start_utc")),
42	            Instant.ofEpochMilli(rs.getLong("end_utc")));
43	
44	    private final JdbcTemplate jdbc;
45	
46	    public PlanRepository(JdbcTemplate jdbc) {
47	        this.jdbc = jdbc;
48	    }
49	
50	    /**
51	     * 插入新计划，返回自增主键。
52	     */
53	    public long insertPlan(String scheduleKey, LocalDate opDate, PlanStatus status, long nowMillis) {
54	        KeyHolder keys = new GeneratedKeyHolder();
55	        jdbc.update(con -> {
56	            PreparedStatement ps = con.prepareStatement(
57	                    "INSERT INTO rail_day_plan (schedule_key, op_date, version, status, created_at, updated_at)"
58	                            + " VALUES (?, ?, 1, ?, ?, ?)",
59	                    Statement.RETURN_GENERATED_KEYS);
60	            ps.setString(1, scheduleKey);
61	            ps.setDate(2, Date.valueOf(opDate));
62	            ps.setString(3, status.name());
63	            ps.setLong(4, nowMillis);
64	            ps.setLong(5, nowMillis);
65	            return ps;
66	        }, keys);
67	        return keys.getKey().longValue();
68	    }
69	
70	    /**
71	     * 按业务键查询计划（不加锁）。
72	     */
73	    public Optional<DayPlan> findByKey(String scheduleKey) {
74	        return jdbc.query("SELECT id, schedule_key, op_date, version, status FROM rail_day_plan"
75	                        + " WHERE schedule_key = ?",
76	                PLAN_MAPPER, scheduleKey).stream().findFirst();
77	    }
78	
79	    /**
80	     * 按业务键查询计划并加行级写锁，须在事务内调用，用于串行化同一计划的更新/发布/取消。
81	     */
82	    public Optional<DayPlan> findByKeyForUpdate(String scheduleKey) {
83	        return jdbc.query("SELECT id, schedule_key, op_date, version, status FROM rail_day_plan"
84	                        + " WHERE schedule_key = ? FOR UPDATE",
85	                PLAN_MAPPER, scheduleKey).stream().findFirst();
86	    }
87	
